from lib import *
S = SS('p46')
steps = [
    step("同一个页面上 16 个选取任务,CSS 能写出来的 13 个(类、属性前缀和包含、子元素、相邻兄弟、第 n 个子元素、:not、并集等),XPath 全都能写,条数一致(取文本和属性的两个任务 XPath 选的是文本或属性节点,CSS 只能选元素)。CSS 表达不了的 3 个:按文字内容选(//a[text()=\"Two\"])、选父元素(//li[a]/parent::ul)、向上找祖先(…/ancestor::div[1])。但 XPath 里匹配 class 要写成 contains(concat(\" \", normalize-space(@class), \" \"), \" item \") 这么长,CSS 的 li.item 只有 7 个字符。", t=tl(S(1)), done=lidx(S(1), '所有商品 li', 'CSS 能表达的 13 个'), mark=lidx(S(1), '文字是 "Two"', '包含 a 的 li', '有 sale 商品'), b=bars([['CSS 能表达的任务', 13, '13'], ['CSS 表达不了的任务', 3, '3'], ['XPath 能表达的任务', 16, '16']], 16, done=[0, 2], mark=[1]), kv=KV([['CSS 能写的', '13 / 16'], ['CSS 写不了的', '按文字选、选父、选祖先'], ['XPath', '16 / 16,但 class 匹配很啰嗦']], ['CSS 写不了的'])),
    step("class 匹配的陷阱(页面里有 class=\"item\"、\"item sale\"、\"itemized\" 等):CSS li.item → 3 个(按空白分隔的词匹配,itemized 不算);XPath //li[@class=\"item\"] → 1 个(整个属性值必须恰好是 item,漏掉 \"item sale\");XPath //li[contains(@class, \"item\")] → 4 个(子串匹配,把 itemized 也选进来了);XPath 写成 contains(concat(\" \", normalize-space(@class), \" \"), \" item \") → 3 个(与 CSS 一致)。", t=tl(S(2)), done=lidx(S(2), 'CSS li.item', '和 CSS 一致'), mark=lidx(S(2), '漏掉', '把 "itemized" 也选进来了'), b=bars([['CSS li.item', 3, '3'], ['XPath @class="item"', 1, '1'], ['XPath contains(@class,…)', 4, '4'], ['XPath 带空格的 contains', 3, '3']], 4, done=[0, 3], mark=[1, 2]), kv=KV([['@class="item"', '漏掉 "item sale"'], ['contains(@class,"item")', '多选 "itemized"'], ['带空格的 contains', '与 CSS 一致']], ['contains(@class,"item")'])),
    step("位置的陷阱:XPath //a[1] 选出 6 个(每个父元素下的第一个 a),(//a)[1] 选出 1 个(整个文档的第一个 a);CSS a:nth-of-type(1) 也是 6 个。XPath 的下标从 1 开始://li[1] 选到 'One¥10',//li[0] 选到 0 个。", t=tl(S(3)), done=lidx(S(3), '(//a)[1]'), mark=lidx(S(3), '//a[1]', 'nth-of-type'), b=bars([['//a[1]', 6, '6'], ['(//a)[1]', 1, '1'], ['CSS a:nth-of-type(1)', 6, '6']], 6, mark=[0, 2], done=[1]), kv=KV([['//a[1]', '每个父元素下的第 1 个,6 个'], ['(//a)[1]', '整个文档第 1 个,1 个'], ['下标', '从 1 开始,//li[0] 选到 0 个']], ['//a[1]'])),
    step("cssselect 把 CSS 翻译成 XPath(lxml 内部就是这样做的):li.item 变成 descendant-or-self::li[@class and contains(@class, 'item') and contains(concat(' ', normalize-space(@class), ' '), ' item ')];a[href^=\"/p/\"] 变成 descendant-or-self::a[@href and starts-with(@href, '/p/')];ul > li:nth-child(2) 变成 …/li[count(preceding-sibling::*) = 1];a + span 变成 …/following-sibling::*[(self::span) and (position() = 1)]。CSS 比手写 XPath 多做了一层翻译,结果等价。", t=tl(S(4)), done=lidx(S(4), 'li.item  ', 'a[href^', 'a + span'), kv=KV([['CSS', '被翻译成 XPath 再执行'], ['li.item', '展开成带 contains 的长表达式'], ['手写 XPath', '少一层翻译']], ['CSS'])),
    step("耗时(5000 个 li 的页面,每项重复 100 次取平均):XPath 字符串每次调用 3.06 ms,预编译 etree.XPath 对象 2.93 ms;CSS 字符串 tree.cssselect 2.77 ms,预编译 CSSSelector 2.84 ms——四者在同一个量级,差别不到 10%,没有稳定的胜者;精确匹配一个属性,XPath 1.29 ms,CSS 1.10 ms。编译一个 CSSSelector 对象 17 微秒,编译一个 etree.XPath 对象 3 微秒。选择器写法对速度的影响远小于对正确性的影响。", t=tl(S(5)), done=lidx(S(5), 'XPath 字符串', 'CSS 字符串', '预编译'), b=bars([['XPath 字符串 ms', 3.06, '3.06'], ['XPath 预编译 ms', 2.93, '2.93'], ['CSS 字符串 ms', 2.77, '2.77'], ['CSS 预编译 ms', 2.84, '2.84']], 3.2, done=[0, 1, 2, 3]), kv=KV([['XPath / CSS', '2.8–3.1 ms,同量级'], ['预编译 vs 字符串', '差别不到 10%'], ['编译开销', 'CSSSelector 17 µs,XPath 3 µs']], ['预编译 vs 字符串'])),
]
A = mkartp('p46', 46, '爬虫,XPath,CSS选择器,lxml,cssselect,选择器,解析,性能,Python,真实验证,动画演示',
    '在同一个页面上比较 XPath 与 CSS 选择器:16 个选取任务中 CSS 能写 13 个、写不了按文字选/选父元素/选祖先 3 个;XPath 里匹配 class 用 @class="item" 只选到 1 个、contains 多选到 4 个、带空格的写法才与 CSS 的 3 个一致;//a[1] 与 (//a)[1] 差 6 个对 1 个;5000 个 li 的页面上两者耗时都在 2.7–3.1 ms,无稳定差别。',
    '写爬虫时用 XPath 还是 CSS 选择器常常是习惯之争。这篇用同一个页面量一量:各自能表达什么、哪些写法有陷阱(尤其 class 匹配和 //a[1])、cssselect 把 CSS 翻译成什么,以及耗时到底差多少。',
    [('13 / 16', '16 个选取任务中 CSS 选择器能写出来的个数(XPath 全部能写)'), ('1 / 4 / 3', 'XPath 用 @class="item"、contains(@class,"item")、带空格的 contains,与 CSS li.item 的 3 个对比选出的条数'), ('2.8–3.1 ms', '5000 个 li 的页面上,XPath 与 CSS(字符串或预编译)每次执行的耗时')],
    [('表达能力', '<p>CSS 能写 16 个任务中的 13 个;写不了的是按文字内容选、选父元素和选祖先——这些要用 XPath(<code>//a[text()="Two"]</code>、<code>/parent::ul</code>、<code>/ancestor::div[1]</code>)。反过来,XPath 里匹配 class 很啰嗦,CSS 的 <code>li.item</code> 更短也更不容易写错。</p>'),
     ('class 的陷阱', '<p>CSS 的 <code>.item</code> 是“按空白分隔的词”匹配。XPath 的 <code>@class="item"</code> 要求整个属性值恰好等于 item(漏掉 <code>item sale</code>),<code>contains(@class, "item")</code> 是子串匹配(多选 <code>itemized</code>),正确写法是 <code>contains(concat(" ", normalize-space(@class), " "), " item ")</code>。</p>'),
     ('位置', '<p><code>//a[1]</code> 是“每个父元素下的第一个 a”,整个文档的第一个要写成 <code>(//a)[1]</code>;XPath 下标从 1 开始。</p>'),
     ('CSS 其实是被翻译成 XPath 的', '<p>lxml 的 <code>cssselect</code> 把 CSS 翻译成 XPath 再执行,<code>li.item</code> 展开成带两层 <code>contains</code> 的长表达式,<code>a + span</code> 展开成 <code>following-sibling</code> 加 <code>position() = 1</code>。结果等价,多一层翻译。</p>'),
     ('耗时', '<p>5000 个 li 的页面上 XPath 和 CSS 的每次执行耗时都在 2.7–3.1 ms,预编译与否差别不到 10%,编译一个选择器只要几到十几微秒。所以选哪一种应由正确性和可读性决定,不是速度。</p>')],
    steps,
    [ENV_P + '。lxml 6.1.1 的 lxml.html 与 cssselect 1.6.0(pip 装进实验专用目录,实验后删除);页面是手写的小页面(任务对比)和 5000 个 li 的生成页面(耗时);耗时每项重复 100 次取平均,编译耗时重复 2000 次;条数一致的判断是直接比较两种写法选出的元素个数',
     '没有验证:更复杂页面上的性能(深层嵌套、大量属性选择器);parsel 的 css/xpath 封装(没有测);XPath 2.0/3.1 与 lxml 不支持的函数;CSS 伪类 :has()、:is() 在 cssselect 里的支持;不同解析器(html5lib、Lexbor)下选择器的行为(selectolax 自带的 CSS 引擎没有测速)'],
    'XPath 与 CSS')
